const requestBody = {
  requests: [
    {
      type: 'execute',
      stmt: {
        sql: "SELECT content FROM prompts WHERE key = 'fact_manager' LIMIT 1"
      }
    },
    {
      type: 'execute',
      stmt: {
        sql: 'SELECT id, fact, category, strength, confidence FROM facts ORDER BY strength DESC LIMIT 100'
      }
    },
    {
      type: 'execute',
      stmt: {
        sql: "SELECT session_id, status, last_active FROM sessions WHERE status = 'active'"
      }
    },
    {
      type: 'execute',
      stmt: {
        sql: "DELETE FROM mood_log WHERE created_at < datetime('now', '-30 days')"
      }
    },
    {
      type: 'execute',
      stmt: {
        sql: "UPDATE facts SET strength = MAX(1, strength - 1) WHERE last_referenced < datetime('now', '-14 days') AND strength > 1"
      }
    }
  ]
};

return [{ json: { requestBody } }];

const dbResult = $input.first().json;
const results = dbResult.results || [];
const parseRows = (result) => {
  if (!result || !result.response || !result.response.result) return [];
  const cols = result.response.result.columns || result.response.result.cols || [];
  const rows = result.response.result.rows || [];
  return rows.map(row => {
    const obj = {};
    cols.forEach((col, i) => {
      const cell = row[i];
      obj[col.name] = (cell && typeof cell === 'object' && 'value' in cell) ? cell.value : cell;
    });
    return obj;
  });
};

const factManagerPrompt = parseRows(results[0])[0]?.content || '';
const allFacts = parseRows(results[1]);
const activeSessions = parseRows(results[2]);

return [{ json: { factManagerPrompt, allFacts, activeSessions } }];

const prevData = $('Parse Results').first().json;
const factsList = prevData.allFacts.map(f => '[' + f.id + '] ' + f.fact + ' (' + f.category + ', strength: ' + f.strength + ')').join('\n');

const messages = [
  { role: 'system', content: prevData.factManagerPrompt },
  { role: 'user', content: 'EXISTING FACTS:\n' + factsList + '\n\nAnalyze and return JSON with actions to take.' }
];

return [{ json: { messages } }];

const llmResponse = $input.first().json;
const content = (llmResponse.choices && llmResponse.choices[0] && llmResponse.choices[0].message && llmResponse.choices[0].message.content) || '';

let actions;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  actions = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
  actions = { actions: [], removed_ids: [] };
}

const stmts = [];
const removedIds = actions.removed_ids || [];

(actions.actions || []).forEach(a => {
  if (a.action === 'add') {
    stmts.push({
      type: 'execute',
      stmt: {
        sql: 'INSERT INTO facts (fact, category, strength, confidence) VALUES (?, ?, ?, ?)',
        args: [
          { type: 'text', value: a.fact || '' },
          { type: 'text', value: a.category || 'general' },
          { type: 'integer', value: a.strength || 5 },
          { type: 'float', value: a.confidence || 0.8 }
        ]
      }
    });
  } else if (a.action === 'update' && a.fact_id) {
    stmts.push({
      type: 'execute',
      stmt: {
        sql: 'UPDATE facts SET fact = ?, category = ?, strength = ?, confidence = ? WHERE id = ?',
        args: [
          { type: 'text', value: a.fact || '' },
          { type: 'text', value: a.category || 'general' },
          { type: 'integer', value: a.strength || 5 },
          { type: 'float', value: a.confidence || 0.8 },
          { type: 'integer', value: a.fact_id }
        ]
      }
    });
  } else if (a.action === 'remove' && a.fact_id) {
    removedIds.push(a.fact_id);
  }
});

removedIds.forEach(id => {
  stmts.push({
    type: 'execute',
    stmt: {
      sql: 'DELETE FROM facts WHERE id = ?',
      args: [{ type: 'integer', value: id }]
    }
  });
});

return [{ json: { requestBody: { requests: stmts } } }];

const prevData = $('Parse Results').first().json;
const activeSessions = prevData.activeSessions || [];
const now = new Date();
const idleThreshold = 24 * 60 * 60 * 1000;

const idleSessions = activeSessions.filter(s => {
  const lastActive = new Date(s.last_active);
  return (now - lastActive) > idleThreshold;
});

if (idleSessions.length === 0) {
  return [{ json: { idle_sessions: [] } }];
}

const requests = idleSessions.map(s => ({
  type: 'execute',
  stmt: {
    sql: 'UPDATE sessions SET status = ? WHERE session_id = ?',
    args: [
      { type: 'text', value: 'archived' },
      { type: 'text', value: s.session_id }
    ]
  }
}));

return [{ json: { requestBody: { requests }, idle_count: idleSessions.length } }];
